'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  check:'<path d="m5 12 4 4L19 6"/>', plus:'<path d="M12 5v14M5 12h14"/>',
  clipboard:'<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m9 14 2 2 4-4"/>',
  card:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 9h4M7 13h10M7 16h7"/>',
  building:'<path d="M5 21V3h14v18M3 21h18M9 7h1m4 0h1M9 11h1m4 0h1M10 21v-5h4v5"/>',
  book:'<path d="M12 5c-3-3-7-2-10-1v15c3-1 7-2 10 1 3-3 7-2 10-1V4c-3-1-7-2-10 1Zm0 0v15"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', up:'<path d="m5 16 5-5 4 3 5-9m-5 0h5v5"/>',
  bin:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3Z"/><circle cx="12" cy="13" r="4"/>',
  leaf:'<path d="M20 3C9 1 2 8 5 15c6 7 17 0 15-12ZM4 21l11-12"/>',
  logout:'<path d="M9 4H4v16h5M9 12h12m-5-5 5 5-5 5"/>',
  share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4m-6 8 6 4"/>',
  shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6ZM8 12l3 3 5-6"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', trash:'<path d="M4 6h16M9 3h6M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.leaf}</svg>`;
const brand = `<a class="brand" href="/" aria-label="Lane Scorecard home"><img src="/assets/mark.svg" alt=""><div>Lane Scorecard<small>NSUT bin pilot</small></div></a>`;
const state = {workspace: localStorage.getItem('lane-workspace') === 'pilot' ? 'pilot' : 'demo', view:'dashboard', lang:localStorage.getItem('lane-lang') || 'en', end:'', data:null, floors:[], cards:[], health:{}, draft:null, render:0};
const t = (en, hi) => state.lang === 'hi' ? hi : en;
const value = (n, suffix = '') => n === null || n === undefined ? '—' : `${Number(n).toLocaleString('en-IN', {maximumFractionDigits:1})}${suffix}`;
const dateLabel = d => new Date(d+'T12:00:00').toLocaleDateString('en-IN', {day:'numeric',month:'short'});
const ratingLabels = {clean:['Clean','साफ़'],few:['A few wrong items','कुछ गलत चीज़ें'],mixed:['Mixed','मिला हुआ'],unseen:['Not seen','नहीं देखा']};
const ratingLabel = r => t(...ratingLabels[r]);
let toastTimer;
function toast(message) { const box=$('#toast'); box.textContent=message; box.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>box.classList.remove('show'),4500); }
async function api(path, options={}) {
  const response=await fetch(path, {credentials:'same-origin', ...options, headers:{'Content-Type':'application/json','X-Lane-Request':'1',...(options.headers||{})}});
  let data; try { data=await response.json(); } catch { throw new Error('The server returned an unreadable response. Please retry.'); }
  if(!response.ok) {
    const detail=Array.isArray(data.detail) ? data.detail.map(x=>`${x.loc?.slice(1).join(' ')}: ${x.msg}`).join('\n') : data.detail;
    const error=new Error(detail || 'The request failed. Please retry.'); error.status=response.status; throw error;
  }
  return data;
}
const endpoint = path => `/api/${state.workspace}/${path}`;
async function confirmAction(title, message, label='Confirm') {
  const modal=$('#modal'); modal.innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="modal-actions"><button class="btn light" data-answer="no">Cancel</button><button class="btn danger" data-answer="yes">${esc(label)}</button></div>`;
  modal.showModal();
  return new Promise(resolve=>{
    const finish=answer=>{ modal.close(); modal.removeEventListener('click',click); modal.removeEventListener('cancel',cancel); resolve(answer); };
    const click=e=>{const button=e.target.closest('[data-answer]');if(button)finish(button.dataset.answer==='yes');};
    const cancel=e=>{e.preventDefault();finish(false);};
    modal.addEventListener('click',click);modal.addEventListener('cancel',cancel);
  });
}
function renameLocation(f) {
  const modal=$('#modal');
  modal.innerHTML=`<h2>Rename location</h2><p>Its checks and photos stay attached. Existing scorecards are refreshed so they never show the old name.</p><form id="rename-form"><label class="field">Location name<input name="name" maxlength="60" required value="${esc(f.name)}"></label><label class="field" style="margin-top:12px">Area <span class="muted">Optional</span><input name="area" maxlength="40" list="area-options" value="${esc(f.area||'')}"></label><div id="rename-error" class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn light" data-answer="no">Cancel</button><button class="btn" type="submit">Save</button></div></form>`;
  modal.showModal();
  const close=()=>modal.close();
  modal.querySelector('[data-answer=no]').addEventListener('click',close);
  modal.querySelector('#rename-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);try{await api(endpoint('floors/'+encodeURIComponent(f.id)),{method:'PUT',body:JSON.stringify({name:fd.get('name'),area:(fd.get('area')||'').trim(),permission:true})});close();await render();toast('Location renamed.');}catch(err){$('#rename-error').textContent=err.message;}});
}
function loginPage(error='') {
  $('#app').innerHTML=`<div class="login"><main class="login-card" id="main">${brand}<form class="login-form" id="login-form"><h2>Sign in</h2><p class="muted">For the team running the NSUT bin pilot. Cleaning staff use their own worker link and do not need this.</p><label class="field">Access code<input name="code" type="password" autocomplete="current-password" required placeholder="Paste your access code" autofocus></label><div class="form-error" id="login-error" role="alert">${esc(error)}</div><button class="btn" type="submit">Sign in</button><p class="hint">Running it on your laptop? The code is in <code>.local/admin-code.txt</code> in the project folder.</p></form></main></div>`;
  $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{await api('/api/login',{method:'POST',body:JSON.stringify({code:new FormData(e.target).get('code')})});await render();}catch(err){$('#login-error').textContent=err.message;button.disabled=false;}});
}
const navItems=[['dashboard','grid','Overview','अवलोकन'],['check','clipboard','Record a check','निरीक्षण दर्ज करें'],['plan','check','Weekly plan','साप्ताहिक योजना'],['cards','card','Scorecards','स्कोरकार्ड'],['history','book','Observation log','निरीक्षण सूची'],['photos','camera','Photos','फ़ोटो'],['setup','building','Pilot setup','पायलट सेटअप'],['guide','leaf','How it works','कैसे काम करता है']];
function shell(content) {
  const name=navItems.find(x=>x[0]===state.view)?.[2] || 'Overview';
  return `<div class="shell"><aside class="sidebar" id="sidebar">${brand}<div class="workspace"><label for="workspace">Workspace</label><select id="workspace"><option value="demo" ${state.workspace==='demo'?'selected':''}>Explore the demo</option><option value="pilot" ${state.workspace==='pilot'?'selected':''}>Your real pilot</option></select></div><nav class="nav" aria-label="Main navigation">${navItems.map(([view,i,en,hi],index)=>`<button data-nav="${view}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${icon(i)}${t(en,hi)}${index===1?'<span class="number">＋</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><button data-action="logout">${icon('logout')} ${t('Sign out','साइन आउट')}</button></div></aside><div class="content"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span class="mobile-brand">Lane Scorecard</span><div class="breadcrumb">${state.workspace==='demo'?t('Demo workspace','डेमो'):t('Real pilot','असली पायलट')} <span>/ &nbsp;${esc(name)}</span></div><div class="top-actions"><span class="status"><span class="status-dot"></span>${state.health.storage==='dynamodb'?'AWS storage':'Local workspace'}</span><button class="lang" data-action="language">${state.lang==='en'?'हिन्दी':'English'}</button><button class="signout" data-action="logout">${icon('logout')}<span>${t('Sign out','साइन आउट')}</span></button></div></header><main class="main" id="main">${state.workspace==='demo'?`<div class="notice">${icon('info')}<span><strong>Demo</strong> &nbsp;Simulated data for practice. Nothing here is real.</span><a href="#setup" data-switch-pilot>Start your real pilot ${icon('arrow')}</a></div>`:`<div class="notice" style="background:#edf3e7;border-color:#d7e1cd;color:#536b42">${icon('shield')}<span><strong>Real pilot</strong> &nbsp;Record only what you actually saw, with permission.</span></div>`}${content}<footer class="footer-line"><span>Lane Scorecard · NSUT campus bin pilot</span><span>Ratings are made by people, not by AI</span></footer></main></div></div>`;
}
function pageHead(eyebrow,title,description,action='') {return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function dateToolbar(label='Your week at a glance') {return `<div class="toolbar"><h3>${label}</h3><label class="date-picker">Week ending <input type="date" id="week-end" value="${state.end}" max="${state.health.today}" aria-label="Week ending"></label></div>`;}
function stat(label,n,suffix,detail,i) {return `<article class="stat"><div class="stat-top">${label}${icon(i)}</div><div class="stat-value">${value(n)}<small>${suffix}</small></div><div class="stat-bottom">${detail}</div></article>`;}
function empty(title,message,button='') {return `<div class="empty">${icon('leaf')}<h2>${title}</h2><p>${message}</p>${button}</div>`;}
function scoreBar(n) {return `<div class="score-cell"><strong>${value(n)}</strong><div class="track"><span style="width:${Number(n)||0}%"></span></div></div>`;}
function trendChart() {
  const trend=state.data.trend,w=540,h=200,left=32,right=15,top=18,bottom=32;
  const x=i=>left+i*(w-left-right)/3,y=n=>top+(100-n)*(h-top-bottom)/100;
  const valid=trend.map((v,i)=>({...v,i})).filter(v=>v.score!==null);
  let paths='',group=[];
  for(let i=0;i<=trend.length;i++) {if(i<trend.length && trend[i].score!==null)group.push(`${x(i)},${y(trend[i].score)}`);else if(group.length){paths+=`<polyline points="${group.join(' ')}" fill="none" stroke="#708d50" stroke-width="2.5"/>`;group=[];}}
  return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Four-week score trend. ${trend.map(v=>`${dateLabel(v.end)}: ${v.score===null?'no data':v.score+' out of 100'}`).join('. ')}">${[0,25,50,75,100].map(v=>`<line class="gridline" x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}"/><text x="0" y="${y(v)+4}">${v}</text>`).join('')}${paths}${valid.map(v=>`<circle cx="${x(v.i)}" cy="${y(v.score)}" r="4.5" fill="#708d50" stroke="white" stroke-width="2"><title>${dateLabel(v.end)}: ${v.score}</title></circle>`).join('')}${trend.map((v,i)=>`<text x="${x(i)}" y="${h-5}" text-anchor="${i===0?'start':i===3?'end':'middle'}">${dateLabel(v.end)}</text>`).join('')}</svg>`;
}
const EXTRA_BINS=[['sanitary','Sanitary waste','सैनिटरी कचरा','Wrapped pads, diapers'],['special','Special-care waste','विशेष देखभाल कचरा','Batteries, bulbs, medicines, needles']];
function extraBins(d) {return `<div style="border-top:1px solid var(--line);padding-top:23px;margin-top:23px"><h3>${t('More bins, if this place has them','अगर यहाँ हैं, तो बाकी डिब्बे')}</h3><p class="muted" style="font-size:12px">${t('The SWM Rules 2026 name four streams. Leave “No such bin” if this site has only two bins; it is not counted.','ठोस अपशिष्ट नियम 2026 में चार धाराएँ हैं। अगर यहाँ दो ही डिब्बे हैं तो “यह डिब्बा नहीं है” छोड़ दें; इसकी गिनती नहीं होगी।')}</p><div class="field-grid">${EXTRA_BINS.map(([k,en,hi,desc])=>`<label class="field">${t(en,hi)} <span class="muted">${desc}</span><select name="${k}"><option value="" ${!d[k]?'selected':''}>${t('No such bin / not checked','यह डिब्बा नहीं है / नहीं देखा गया')}</option>${Object.keys(ratingLabels).map(r=>`<option value="${r}" ${d[k]===r?'selected':''}>${ratingLabel(r)}</option>`).join('')}</select></label>`).join('')}</div></div>`;}
function deepDue(floorId) {return (state.data?.deep_plan||[]).some(f=>f.id===floorId&&!f.done);}
function deepPanel() {const plan=state.data.deep_plan||[];return `<article class="panel"><div class="panel-head"><h3>Deep checks this week</h3>${icon('shield')}</div><p class="muted" style="font-size:12px">Look below the top layer on these floors. A new random pick each week, visible only to operators, so hiding wrong items at the bottom is risky.</p>${plan.length?plan.map(f=>`<div class="data-list"><span>${esc(f.name)}</span><strong>${f.done?'Done':'Due'}</strong></div>`).join(''):'<p class="muted" style="font-size:12px">Add locations first.</p>'}<p class="muted" style="font-size:10px;margin-top:8px">${state.data.deep_checks||0} deep checks this week · hidden wrong items found in ${state.data.hidden_found||0}</p></article>`;}
function goalPanel() {const g=state.data.goal;if(!g)return '';return `<article class="panel"><div class="panel-head"><h3>Campus goal · proposal</h3>${icon('up')}</div><div class="stat-value" style="font-size:28px">${g.streak}<small> / ${g.weeks} weeks</small></div><p class="muted" style="font-size:12px">Weeks in a row with both bins clean in ≥${g.target_rate}% of checks (at least ${g.min_checks} checks). ${g.weeks_met} of the last ${g.weeks} weeks met it.</p><p class="muted" style="font-size:10px;margin-top:8px">Idea for the pilot: a campus that holds the goal applies for a shared benefit, such as priority for a public EV charging point. Not an existing scheme. No household points or money.</p></article>`;}
function binsPanel() {return `<article class="panel"><h3>Inside the bins</h3>${[['bio','Green bin · degradable (kitchen waste)','Food & plant waste'],['nonbio','Blue bin · non-degradable (recyclable)','Dry packaging & other waste']].map(([key,label,desc])=>`<div class="bin-row"><span class="bin-icon ${key==='nonbio'?'dry':''}">${icon('bin')}</span><div class="bin-details"><div class="bin-title"><span>${label}</span><strong>${value(state.data.streams[key])}<small> /100</small></strong></div><div class="track ${key==='nonbio'?'dry':''}"><span style="width:${state.data.streams[key]||0}%"></span></div><small style="font-size:9px">${desc}</small></div></div>`).join('')}${EXTRA_BINS.filter(([k])=>state.data.streams[k]!=null).map(([k,label,,desc])=>`<div class="bin-row"><span class="bin-icon dry">${icon('bin')}</span><div class="bin-details"><div class="bin-title"><span>${label}</span><strong>${value(state.data.streams[k])}<small> /100</small></strong></div><div class="track dry"><span style="width:${state.data.streams[k]||0}%"></span></div><small style="font-size:9px">${desc}</small></div></div>`).join('')}<p class="muted" style="font-size:10px">Average rating of observed bins. Missing bins excluded.</p></article>`;}
function floorTable() {
  const rows=state.data.floors;
  if(!rows.length)return empty('No bin locations yet.','Add the campus bin pairs you will check in Pilot setup, then record the first check.',`<button class="btn" data-nav="setup">${icon('plus')} Add a location</button>`);
  return `<div class="table-scroll"><table class="floor-table"><thead><tr><th>Location</th><th>Score / 100</th><th class="hide-mobile">Checks</th><th>Coverage</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="floor-cell"><span class="floor-symbol">${icon('building')}</span>${esc(f.name)}</div></td><td>${scoreBar(f.score)}</td><td class="hide-mobile">${f.checks}</td><td><span class="pill ${f.coverage===null?'gray':f.coverage<100?'amber':''}">${value(f.coverage,'%')}</span></td><td><button class="text-btn" data-card="${esc(f.id)}" ${!f.checks?'disabled':''}>Scorecard ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;
}
function overview() {
  const d=state.data,delta=d.score!==null&&d.previous.score!==null?Math.round((d.score-d.previous.score)*10)/10:null;
  return pageHead('',t('Overview','अवलोकन'),t('This week across all bin locations.','इस हफ़्ते सभी बिन जगहों का हाल।'),`<button class="btn" data-nav="check">${icon('plus')} ${t('Record a check','निरीक्षण दर्ज करें')}</button>`)+dateToolbar()+`<section class="stats" aria-label="Weekly metrics">${stat('Campus score',d.score,'/ 100',delta===null?'No previous-week comparison':`<strong>${delta>0?'+':''}${delta} points</strong> vs previous week`,'up')}${stat('Both bins clean',d.both_clean_rate,'%',`${d.both_clean_count} of ${d.complete_checks} fully observed checks`,'leaf')}${stat('Checks recorded',d.checks,'checks',`${d.active_floors} of ${d.total_floors} locations with a score`,'clipboard')}${stat('Observation coverage',d.coverage,'%',`Observed bins ÷ all bins in recorded checks`,'shield')}</section><div class="grid-main"><div><article class="panel"><div class="panel-head"><div><h2>Your campus, week by week</h2><p>Campus score · four consecutive weeks</p></div><span class="chart-key">${state.workspace==='demo'?'Simulated':'Pilot'} scores</span></div>${trendChart()}<div class="chart-footer">${icon('info')}${state.workspace==='demo'?'Illustrative trend. This is not evidence of real-world impact.':'An early pilot signal, not proof that scorecards caused a change.'}</div></article><article class="panel section-gap"><div class="panel-head"><div><h2>Every floor has a part to play</h2><p>Private operator view · alphabetical, not a leaderboard</p></div><button class="text-btn" data-nav="cards">View cards</button></div>${floorTable()}</article></div><aside class="side-stack"><article class="action-panel"><h2>Share feedback</h2><p>Make a private card for each location, in English and Hindi, and share the link with the people who use those bins.</p><button class="btn" data-nav="cards">Make a scorecard ${icon('arrow')}</button><img src="/assets/mark.svg" alt="" class="leaf-art"></article>${binsPanel()}${deepPanel()}${goalPanel()}<article class="panel"><div class="panel-head"><h3>After the bin check</h3>${icon('share')}</div><p class="muted" style="font-size:12px">Was waste kept separate during collection?</p><div class="stat-value" style="font-size:28px">${value(d.separate_rate)}<small>%</small></div><p class="muted" style="font-size:10px;margin-top:8px">${d.cart_observed} collection observations · unknown excluded</p></article></aside></div>`;
}
const ISSUE_LABELS={plastic_in_wet:['🛍','Plastic in the green (wet) bin','हरे (गीले) डिब्बे में प्लास्टिक'],food_in_dry:['🍛','Food in the blue (dry) bin','नीले (सूखे) डिब्बे में खाना'],hidden_below:['🔍','Wrong items hidden under the top layer','ऊपर की परत के नीचे ग़लत चीज़ें छिपी थीं'],one_bag:['👜','Everything in one bag','सब कुछ एक ही थैली में']};
function newDraft(check=null) {return check?{...check,issues:[...(check.issues||[])],editing:check.id,photos:[...check.photos],photoData:{},dirty:false}:{floor_id:state.floors[0]?.id||'',date:state.health.today,round:'morning',bio:'',nonbio:'',sanitary:'',special:'',deep:false,kept_separate:'',issues:[],note:'',photos:[],photoData:{},human_confirmed:false,dirty:false};}
function checkPage() {
  if(!state.floors.length)return pageHead('',t('Record a check','निरीक्षण दर्ज करें'),'A bin location needs to exist before its first observation.')+`<section class="panel">${empty('No locations yet.','Add a bin location you have permission to check.',`<button class="btn" data-nav="setup">${icon('plus')} Add your first location</button>`)}</section>`;
  if(!state.draft)state.draft=newDraft();
  const d=state.draft;
  return pageHead('',d.editing?'Correct a check':t('Record a check','निरीक्षण दर्ज करें'),'Look at what is visible. Make the final call yourself.')+`<form id="check-form" class="form-layout"><div class="form-stack"><section class="panel"><div class="step-label"><span>1</span><h3>Where and when</h3></div><div class="field-grid"><label class="field full">Location<select name="floor_id" required ${d.editing?'disabled':''}>${state.floors.map(f=>`<option value="${esc(f.id)}" ${f.id===d.floor_id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label class="field">Date<input type="date" name="date" value="${d.date}" max="${state.health.today}" required ${d.editing?'disabled':''}></label><label class="field">Round<select name="round" ${d.editing?'disabled':''}>${d.round==='collection'?'<option value="collection" selected>Collection (staff report)</option>':''}<option value="morning" ${d.round==='morning'?'selected':''}>Morning</option><option value="evening" ${d.round==='evening'?'selected':''}>Evening</option></select></label></div></section><section class="panel"><div class="step-label"><span>2</span><h3>${t('Check each bin','हर कूड़ेदान की जाँच करें')}</h3></div>${['bio','nonbio'].map(s=>`<div style="${s==='nonbio'?'border-top:1px solid var(--line);padding-top:23px;margin-top:23px':''}"><div class="bin-heading"><span class="bin-icon ${s==='nonbio'?'dry':''}">${icon('bin')}</span><div><h3>${s==='bio'?t('Green bin · degradable (kitchen waste)','हरा डिब्बा · गीला (रसोई) कचरा'):t('Blue bin · non-degradable (recyclable)','नीला डिब्बा · सूखा (रीसायकल) कचरा')}</h3><p>${s==='bio'?'Food scraps and plant waste':'Dry packaging and other non-bio waste'}</p></div></div><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">${s==='bio'?'Green':'Blue'} bin rating</legend><div class="rating-grid">${Object.keys(ratingLabels).map((r,i)=>`<label class="rating"><input type="radio" name="${s}" value="${r}" required ${d[s]===r?'checked':''}><span class="rating-mark">${['✓','~','×','?'][i]}</span>${ratingLabel(r)}<small>${['100 points','50 points','0 points','Not scored'][i]}</small></label>`).join('')}</div></fieldset><div class="photo-zone" id="photo-${s}">${photoZone(s)}</div></div>`).join('')}${extraBins(d)}</section><section class="panel"><div class="step-label"><span>3</span><h3>Finish the observation</h3></div><div class="field-grid"><label class="field full">Kept separate during collection?<select name="kept_separate"><option value="" ${d.kept_separate===null||d.kept_separate===''?'selected':''}>Not observed / not collected yet</option><option value="yes" ${d.kept_separate===true||d.kept_separate==='yes'?'selected':''}>Yes — kept separate</option><option value="no" ${d.kept_separate===false||d.kept_separate==='no'?'selected':''}>No — mixed during collection</option></select></label><label class="check-label full"><input type="checkbox" name="deep" ${d.deep?'checked':''}><span>${t('Deep check: I looked below the top layer','गहरी जाँच: मैंने ऊपर की परत के नीचे भी देखा')}${deepDue(d.floor_id)?` <span class="pill amber">${t('Due for this floor this week','इस हफ़्ते इस फ़्लोर की बारी')}</span>`:''}</span></label><fieldset class="field full" style="border:0;padding:0;margin:0"><legend>${t('What was wrong?','क्या ग़लत था?')} <span class="muted">${t('Optional · tick all you saw','वैकल्पिक · जो देखा सब चुनें')}</span></legend>${Object.entries(ISSUE_LABELS).map(([k,[e,en,hi]])=>`<label class="check-label" style="margin-top:8px"><input type="checkbox" name="issues" value="${k}" ${(d.issues||[]).includes(k)?'checked':''}><span>${e} ${t(en,hi)}</span></label>`).join('')}</fieldset><label class="field full">Notes <span class="muted">Optional · no personal information</span><textarea name="note" maxlength="500" placeholder="For example: snack wrappers in the green bin.">${esc(d.note)}</textarea></label></div><label class="check-label" style="margin-top:20px"><input type="checkbox" name="human_confirmed" required ${d.human_confirmed?'checked':''}><span>${t('I personally checked these bins and confirmed the ratings.','मैंने स्वयं इन कूड़ेदानों की जाँच करके रेटिंग की पुष्टि की है।')}</span></label><div id="check-error" class="form-error" role="alert"></div><div class="form-actions"><small>${state.workspace==='demo'?'This will be saved as simulated demo data.':'This will be saved as a real pilot observation.'}</small><button type="submit" class="btn">${icon('check')} ${d.editing?'Save correction':t('Save observation','निरीक्षण सहेजें')}</button></div></section></div><aside class="side-stack"><section class="panel"><h3 style="margin-bottom:22px">A good check is an honest check.</h3><ul class="help-list"><li>${icon('check')}<div><strong>Clean</strong>No visibly misplaced items.</div></li><li>${icon('info')}<div><strong>A few wrong items</strong>Mostly sorted, with a little visible contamination.</div></li><li>${icon('bin')}<div><strong>Mixed</strong>Clearly mixed contents; substantial wrong material.</div></li><li>${icon('camera')}<div><strong>Not seen</strong>Missing, empty, obscured or not safely assessable. Don’t guess.</div></li></ul></section><section class="action-panel"><div class="eyebrow">AI is a second pair of eyes</div><h2>You make the call.</h2><p>Photo suggestions never set a rating automatically. Only your confirmed observation affects the score.</p><p style="margin-top:10px">${state.health.ai_configured?'Bedrock configured. Availability is checked per photo.':'AI is not connected. Manual checks work in full.'}</p></section></aside></form>`;
}
function photoZone(stream) {
  const p=state.draft.photoData[stream];
  if(p)return `<div class="photo-result"><img src="${endpoint('photos/'+encodeURIComponent(p.id))}" alt="${stream==='bio'?'Green':'Blue'} bin observation"><div><strong>${p.suggestion.status==='available'?'AI suggestion: '+esc(ratingLabel(p.suggestion.rating)):'Photo attached'}</strong><p>${esc(p.suggestion.reason)}</p><button type="button" class="text-btn" data-remove-photo="${stream}">Remove photo</button></div></div>`;
  if(state.draft.editing && state.draft.photos.length)return '<p>Existing photos are preserved for this correction. To replace photos, delete and re-record the check.</p>';
  return `<label>${icon('camera')} Add a photo <span class="muted">Optional · max 2 MB</span><input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${stream}" aria-label="Upload ${stream} bin photo"></label><p class="muted" style="margin-top:8px">Use only bin photos you have permission to share. No faces or identifying details. ${state.health.ai_configured?'This photo will be sent to AWS for analysis.':'Stored privately on the app server.'}</p>`;
}
function cardsPage() {
  return pageHead('',t('Scorecards','स्कोरकार्ड'),'A private card for each bin location. One next step, in English and Hindi.')+dateToolbar('Choose a location to give feedback')+(!state.data.floors.length?`<div class="panel">${empty('Start with a real observation.','Set up your floors and record checks before generating cards.',`<button class="btn" data-nav="setup">Set up pilot ${icon('arrow')}</button>`)}</div>`:`<section class="cards-grid">${state.data.floors.map(f=>{const card=state.cards.find(c=>c.id===f.id&&c.end===state.end);const observed=Object.values(f.streams).some(x=>x!==null);return `<article class="mini-card"><div class="card-top"><h3>${esc(f.name)}</h3>${icon('leaf')}</div><div class="card-body"><div class="eyebrow">${state.workspace==='demo'?'Simulated':'Real pilot'} · ${dateLabel(state.end)}</div><div class="card-score">${value(f.score)}<small>/100</small></div><p class="compare">Campus median: ${value(state.data.median)} · ${f.checks} checks</p><p class="tip">${observed?'Give this location a private comparison and a practical action for its weakest bin.':'No scored observations yet. Record what you can see before giving feedback.'}</p><div class="card-actions"><button class="btn small" data-card="${esc(f.id)}" ${!f.checks?'disabled':''}>${card?'Refresh card':'Create card'} ${icon('arrow')}</button>${card?`<a class="btn light small" href="/card/${card.token}" target="_blank" rel="noopener">Open</a><button class="btn light small" data-copy="${card.token}" aria-label="Copy ${esc(f.name)} card link">${icon('share')}</button><button class="text-btn" data-revoke="${card.token}">Revoke</button>`:''}</div>${card?`<p class="muted" style="font-size:10px;margin-top:12px">Snapshot created ${esc(new Date(card.generated_at).toLocaleString('en-IN'))}</p>`:''}</div></article>`;}).join('')}</section>`)+`<div class="notice section-gap">${icon('shield')} Anyone with a scorecard link can read that card. It contains no photos, notes, resident names or other floors’ scores. Revoke a link at any time.</div>`;
}
function historyPage() {
  const d=state.data,names=Object.fromEntries(state.floors.map(f=>[f.id,f.name]));
  return pageHead('','Observation log','Review, correct or remove a check. Corrections revoke existing workspace cards.',`<a class="btn light" href="${endpoint('export.csv')}?end=${state.end}" download>${icon('download')} Export CSV</a>`)+dateToolbar('Observation log')+`<section class="panel">${!d.recent.length?empty('No checks in this week.','Choose a different week or record your first observation.',`<button class="btn" data-nav="check">Record a check</button>`):`<div class="table-scroll"><table class="floor-table"><thead><tr><th>Location / Date</th><th>Green</th><th>Blue</th><th>Collection</th><th>Actions</th></tr></thead><tbody>${d.recent.map(c=>`<tr><td><strong>${esc(names[c.floor_id])}</strong><br><small>${dateLabel(c.date)} · ${c.round}</small>${c.note?`<details style="max-width:240px;margin-top:6px"><summary class="muted">Notes</summary><p style="white-space:pre-wrap">${esc(c.note)}</p></details>`:''}${c.photos.length?`<button class="text-btn" data-photos-for="${esc(c.floor_id)}|${esc(c.date)}" style="margin-right:10px">View photos (${c.photos.length})</button>`:''}${c.photos.map(p=>`<a class="text-btn" href="${endpoint('photos/'+encodeURIComponent(p))}" target="_blank" rel="noopener">Photo</a>`).join(' ')}</td><td><span class="pill ${c.bio==='mixed'?'red':c.bio==='few'?'amber':c.bio==='unseen'?'gray':''}">${ratingLabel(c.bio)}</span></td><td><span class="pill ${c.nonbio==='mixed'?'red':c.nonbio==='few'?'amber':c.nonbio==='unseen'?'gray':''}">${ratingLabel(c.nonbio)}</span></td><td>${c.kept_separate===null?'Not observed':c.kept_separate?'Kept separate':'Mixed'}</td><td><div style="display:flex;gap:12px"><button class="text-btn" data-edit="${esc(c.id)}">Edit</button><button class="text-btn" data-delete-check="${esc(c.id)}" style="color:var(--red)">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`}</section><section class="panel section-gap"><div class="panel-head"><div><h2>Photo helper: measured, not assumed</h2><p>Agreement with the operator’s final rating on attached photos in this week.</p></div></div>${['bio','nonbio'].map(s=>{const e=d.evaluation[s];return `<div class="data-list"><span>${s==='bio'?'Green':'Blue'} bin</span><strong>${e.total?value(e.matched/e.total*100,'%'):'Not evaluated'} <small>(${e.matched} / ${e.total})</small></strong></div>`;}).join('')}<p class="muted" style="font-size:11px;margin-top:15px">This is operator agreement, not independently measured model accuracy. ${state.workspace==='demo'?'Demo checks are not real evaluation evidence.':'Use a separate, independently labelled photo set for a formal evaluation.'}</p></section>`;
}
function workerLinkUrl() {return `${location.origin}/w/${state.workerLink}`;}
function workerPanel() {
  const intro='<h3>Collection staff link</h3><p>Housekeeping and sanitation staff see every bin at pickup. This link opens a picture-only page with Hindi voice prompts: they tap the place, tap how each bin looks, and flag dangerous items. No sign-in, no reading needed. Their reports count as checks in the <strong>collection</strong> round.</p>';
  if(!state.workerLink)return `<section class="panel prose">${intro}<button class="btn" data-action="worker-create">${icon('plus')} Create worker link</button></section>`;
  const share=encodeURIComponent('Lane Scorecard — कूड़ेदान की रिपोर्ट के लिए यह लिंक खोलें: '+workerLinkUrl());
  return `<section class="panel prose">${intro}<p class="muted" style="word-break:break-all">${esc(workerLinkUrl())}</p><div class="modal-actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="btn light" data-action="worker-copy">Copy link</button><a class="btn light" href="https://wa.me/?text=${share}" target="_blank" rel="noopener">Share on WhatsApp</a><button class="btn light" data-action="worker-create">New link</button><button class="text-btn" data-action="worker-revoke" style="color:var(--red)">Turn off</button></div><p class="muted">Anyone with the link can add reports to this workspace. Make a new link or turn it off if it is shared too widely.</p></section>`;
}
function setupPage() {
  return pageHead('','Pilot setup','Use place labels, not student names. Add only bins you have permission to check.')+`<div class="form-layout"><section class="panel"><div class="panel-head"><h2>Bin locations in this workspace</h2><span class="pill">${state.floors.length} / 200</span></div>${state.floors.length?state.floors.map(f=>`<div class="data-list"><span>${icon('building')} &nbsp;${esc(f.name)}${f.area?` <small class="muted">· ${esc(f.area)}</small>`:''}</span><span style="display:flex;gap:16px;flex-shrink:0"><button class="text-btn" data-rename-floor="${esc(f.id)}">Rename</button><button class="text-btn" data-delete-floor="${esc(f.id)}" style="color:var(--red)">Remove</button></span></div>`).join(''):'<p class="muted" style="margin-bottom:22px">No locations added yet. Your real pilot starts with a clean slate.</p>'}<form id="floor-form" style="margin-top:25px"><label class="field">Location name<input name="name" maxlength="60" required placeholder="For example: Canteen · front, or Library · entrance"></label><label class="field" style="margin-top:14px">Area <span class="muted">Optional · groups locations across campus</span><input name="area" maxlength="40" list="area-options" placeholder="For example: Academic blocks"><datalist id="area-options">${["Academic blocks","Hostels","Canteen & food","Library","Sports","Admin & offices","Labs & workshops","Gates & roads"].map(a=>`<option value="${a}">`).join("")}</datalist></label><label class="check-label" style="margin:17px 0"><input name="permission" type="checkbox" required><span>I have permission to check these shared bins and share location-level feedback.</span></label><div id="floor-error" class="form-error" role="alert"></div><button class="btn" type="submit">${icon('plus')} Add location</button></form></section><aside class="side-stack">${workerPanel()}<section class="panel prose"><h3>Adding locations</h3><p>One location per green and blue bin pair. Name it after the place (“Library · entrance”), never a person, and pick its area so the plan and report can group it. Check the same locations on every round.</p></section><section class="panel prose"><h3>Your workspace</h3><div class="data-list"><span>Storage</span><strong>${state.health.storage==='dynamodb'?'AWS DynamoDB':'Local SQLite'}</strong></div><div class="data-list"><span>Photo helper</span><strong>${state.health.ai_configured?'Configured':'Not connected'}</strong></div><div class="data-list"><span>Data mode</span><strong>${state.workspace==='demo'?'Simulated demo':'Real pilot'}</strong></div><p>Removing a location deletes its checks and attached photos, and revokes all scorecards in that workspace. Unattached photos are removed by the maintenance command.</p></section></aside></div>`;
}
function outcomeText(o) {
  // Our rule, not a statistical proof (see app/actions.py): compare only checks where both bins were seen.
  const n=o.compared_checks?` (${o.compared_checks[0]} → ${o.compared_checks[1]} checks with both bins seen)`:'';
  if(o.status==='improved')return t(`Clearly better than last week: up ${o.change} points${n}.`,`पिछले हफ़्ते से साफ़ बेहतर: ${o.change} अंक ऊपर${n}।`);
  if(o.status==='worse')return t(`Clearly worse than last week: down ${Math.abs(o.change)} points${n}.`,`पिछले हफ़्ते से साफ़ ख़राब: ${Math.abs(o.change)} अंक नीचे${n}।`);
  if(o.status==='no_clear_change')return t(`Score ${o.delta>0?'+':''}${o.delta} since last week, within normal week-to-week ups and downs. No clear change yet${n}.`,`पिछले हफ़्ते से स्कोर में ${o.delta} का अंतर, जो सामान्य उतार-चढ़ाव में है। अभी साफ़ बदलाव नहीं${n}।`);
  if(o.status==='too_few_checks')return t(`Fewer than 3 checks with both bins seen in one of the two weeks${n}. Too few to judge.`,`दोनों में से किसी हफ़्ते में दोनों डिब्बे देखे गए 3 से कम निरीक्षण${n}। आँकने के लिए कम।`);
  if(o.status==='no_baseline')return t('No score last week to compare with yet.','पिछले हफ़्ते का स्कोर अभी तुलना के लिए नहीं है।');
  return t('Not enough observations yet to judge the change.','बदलाव आँकने के लिए अभी पर्याप्त निरीक्षण नहीं हैं।');
}
function planPage() {
  const actions=state.data.actions;
  const kinds={safety:['Worker safety','red'],collection:['Collection follow-up','amber'],observe:['More observation needed','gray'],segregation:['Bin separation','amber'],maintain:['Keep the routine','']};
  const download=`<a class="btn" href="${endpoint('report.html')}?end=${encodeURIComponent(state.end)}&lang=${state.lang==='hi'?'hi':'en'}" download>${icon('download')} ${t('Download weekly report','साप्ताहिक रिपोर्ट डाउनलोड करें')}</a>`;
  return pageHead('',t('Weekly plan','साप्ताहिक योजना'),t('Use the evidence from this week to plan the next round.','इस हफ़्ते के निरीक्षणों से अगली जाँच की योजना बनाएँ।'),download)+dateToolbar('Your weekly action plan')+
    `<div class="plan-intro">${icon('info')}<p>These actions follow your recorded observations. Dangerous items flagged by collection staff come first, then collection mixing, then missing observations, then bin separation. Locations are grouped by campus area, then listed alphabetically.</p></div>`+
    (actions.length?`<div class="plan-grid">${actions.map(a=>`<article class="panel plan-card"><div class="panel-head"><h2>${esc(a.name)}${a.area?`<small class="muted" style="display:block;font-size:12px;font-weight:500">${esc(a.area)}</small>`:''}</h2><span class="pill ${kinds[a.kind][1]}">${kinds[a.kind][0]}</span></div><h3>${esc(a.title)}</h3><p class="plan-evidence">${esc(a.evidence)}</p><div class="tip-box"><p>${esc(a.action[state.lang]||a.action.en)}</p></div><p class="plan-evidence">${esc(outcomeText(a.outcome))}</p><div class="plan-meta"><span>${a.checks} checks · ${value(a.coverage,'%')} coverage</span><strong>${value(a.score)} /100</strong></div><button class="text-btn" data-followup="${esc(a.floor_id)}">${t('Record the next check','अगला निरीक्षण दर्ज करें')} ${icon('arrow')}</button>${collectionTrackButton(a)}</article>`).join('')}</div>`:
    `<section class="panel">${empty('Start with one location.','Add a location with permission. Its first observation will give you a useful next step.','<button class="btn" data-nav="setup">Add a location</button>')}</section>`)+
    followupsPanel()+`<section class="panel section-gap prose"><h3>A report for the warden or estate office</h3><p>The download includes this week’s location scores, observation coverage, collection observations and next steps. Open the downloaded report in a browser and print or save it as PDF.</p><p>Private notes and photos are excluded. Share only with the people who use these bins. Downloaded copies do not update after corrections and cannot be revoked.</p></section>`;
}
function photosPage() {
  const all=state.photos||[], f=state.photoFilter||(state.photoFilter={floor:'',date:''});
  const label=r=>r.stream==='bio'?t('Green bin','हरा डिब्बा'):r.stream==='nonbio'?t('Blue bin','नीला डिब्बा'):esc(r.stream);
  const rows=all.filter(r=>(!f.floor||(r.check&&r.check.floor_id===f.floor))&&(!f.date||(r.check&&r.check.date===f.date)));
  // One group per check: location + day + round, newest day first.
  const groups=[];
  for(const r of [...rows].sort((a,b)=>((b.check?.date||'')+(b.check?.round||'')).localeCompare((a.check?.date||'')+(a.check?.round||''))||(a.check?.location||'').localeCompare(b.check?.location||''))){
    const key=r.check?r.check.id:'loose';let g=groups.find(x=>x.key===key);if(!g)groups.push(g={key,check:r.check,items:[]});g.items.push(r);}
  const card=r=>`<article class="panel photo-card"><img src="${endpoint('photos/'+encodeURIComponent(r.id))}" alt="${label(r)} photo" loading="lazy" style="width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px;background:#eef3e7">
    <div style="margin-top:10px"><strong>${label(r)}</strong><p class="muted" style="margin:4px 0 10px">${r.check?`${esc(r.check.location)} · ${dateLabel(r.check.date)} · ${esc(r.check.round)}`:t('Not attached to a check','किसी निरीक्षण से नहीं जुड़ी')}</p>
    <button class="btn light" data-delete-photo="${esc(r.id)}" data-check="${r.check?esc(r.check.id):''}" style="color:var(--red)">${t('Delete photo','फ़ोटो हटाएँ')}</button></div></article>`;
  const head=g=>g.check?`<h3 class="photo-group">${esc(g.check.location)}${g.check.area?` <small class="muted">· ${esc(g.check.area)}</small>`:''} <span class="muted" style="font-weight:500">— ${dateLabel(g.check.date)} · ${esc(g.check.round)} · ${g.items.length} ${t(g.items.length===1?'photo':'photos','फ़ोटो')}</span></h3>`:`<h3 class="photo-group">${t('Not attached to a check','किसी निरीक्षण से नहीं जुड़ी')}</h3>`;
  const filters=`<div class="toolbar" style="flex-wrap:wrap;gap:12px"><h3>${t('Show photos for','इनकी फ़ोटो दिखाएँ')}</h3><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">
    <label class="date-picker">${t('Location','जगह')} <select id="photo-floor" aria-label="Location"><option value="">${t('All locations','सभी जगहें')}</option>${state.floors.map(x=>`<option value="${esc(x.id)}" ${f.floor===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
    <label class="date-picker">${t('Day','दिन')} <input type="date" id="photo-date" value="${esc(f.date)}" max="${state.health.today}" aria-label="Day"></label>
    ${f.floor||f.date?`<button class="text-btn" data-action="photo-clear">${t('Show all','सब दिखाएँ')}</button>`:''}</div></div>`;
  return pageHead('',t('Photos','फ़ोटो'),t('Pick a location and a day to see exactly which photos belong to that check. If one is wrong — wrong bin, a person in it, too dark — delete it here. The check and its ratings stay as they are.','जगह और दिन चुनें और देखें कि उस निरीक्षण की कौन-सी फ़ोटो हैं। अगर कोई ग़लत है — ग़लत डिब्बा, उसमें कोई व्यक्ति, बहुत अँधेरा — तो यहाँ हटाएँ। निरीक्षण और उसकी रेटिंग वैसी ही रहेंगी।'))+filters+
    `<p class="muted" style="margin:0 0 14px">${rows.length} ${t('of','में से')} ${all.length} ${t('photos shown','फ़ोटो दिख रही हैं')}</p>`+
    (rows.length?groups.map(g=>`<section class="section-gap">${head(g)}<div class="plan-grid" style="grid-template-columns:repeat(auto-fill,minmax(230px,1fr))">${g.items.map(card).join('')}</div></section>`).join(''):
    `<section class="panel">${empty(all.length?t('No photos for this location and day.','इस जगह और दिन की कोई फ़ोटो नहीं।'):t('No photos yet.','अभी कोई फ़ोटो नहीं।'),all.length?t('Choose another day, or press Show all.','दूसरा दिन चुनें, या सब दिखाएँ दबाएँ।'):t('Photos you add while recording a check appear here.','निरीक्षण दर्ज करते समय जोड़ी गई फ़ोटो यहाँ दिखेंगी।'),all.length?'<button class="btn light" data-action="photo-clear">Show all</button>':`<button class="btn" data-nav="check">${icon('plus')} ${t('Record a check','निरीक्षण दर्ज करें')}</button>`)}</section>`);
}
function guidePage() {
  return pageHead('','How it works','Simple scoring. Visible limits. A human behind every observation.')+`<div class="rules-grid"><section class="panel prose"><h2>One complete feedback loop</h2><ul><li>Record the visible condition of both bins.</li><li>Compare a location’s score with the campus median.</li><li>Share one useful action in English or Hindi.</li><li>Repeat the check and observe any change.</li></ul><p>No cash rewards, public resident rankings or invented impact claims.</p><h3>How a score is calculated</h3><p>Clean = 100. A few wrong items = 50. Mixed = 0. Not seen is excluded, never counted as clean.</p><p>We average each bin type’s observed ratings over seven days, then average the available bin-type scores for each location. The campus score is the average of scored locations; the median is the middle floor score.</p><p>Coverage is the proportion of bin ratings that were actually observed. A high score with low coverage is incomplete evidence.</p><h3>Both bins clean</h3><p>The percentage of fully observed checks where both bins were rated clean. Checks with either bin marked “not seen” are excluded from this denominator.</p></section><section class="panel prose"><h2>Built for this pilot</h2><details open><summary>Two bins, not a legal compliance certificate</summary><p>This campus pilot uses NSUT’s paired green (degradable, kitchen waste) and blue (non-degradable, recyclable) bins. Local collection arrangements may differ. It does not measure compliance with a national four-stream waste rule. The CSV is our own observation log.</p></details><details open><summary>Photos and AI</summary><p>Photos are optional and private to operators. Metadata is stripped during processing. When Bedrock is connected, it suggests a rating; the operator chooses the final answer. When AI is unavailable, no prediction is fabricated.</p></details><details open><summary>Privacy and sharing</summary><p>No resident identities are needed. A scorecard link reveals only its location’s aggregate feedback and the campus median. Treat the link as private; anyone holding it can read it. You can revoke it.</p></details><details open><summary>What this can demonstrate</summary><p>Repeated real observations can show an early pilot trend. They do not establish causation. Demo trends are generated examples. Report independently collected data and evaluation results honestly.</p></details></section></div>`;
}
async function render() {
  const serial=++state.render;
  try {
    if(!state.health.today)state.health=await api('/api/health');
    state.end ||= state.health.today;
    const ws=state.workspace;
    const [data,floors,cards,followups]=await Promise.all([api(`/api/${ws}/dashboard?end=${state.end}`),api(`/api/${ws}/floors`),api(`/api/${ws}/cards`),state.view==='plan'?api(`/api/${ws}/followups`):Promise.resolve([])]);
    if(serial!==state.render)return;
    state.followups=followups;state.data=data;state.floors=floors.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));state.data.floors.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));state.cards=cards;
    if(state.view==='setup')state.workerLink=(await api(`/api/${ws}/worker-link`)).token;
    if(state.view==='photos')state.photos=await api(`/api/${ws}/photos`);
    if(serial!==state.render)return;
    const pages={photos:photosPage,dashboard:overview,check:checkPage,plan:planPage,cards:cardsPage,history:historyPage,setup:setupPage,guide:guidePage};
    $('#app').innerHTML=shell((pages[state.view]||overview)());bind();
  } catch(error) {
    if(error.status===401)loginPage();
    else {$('#app').innerHTML=`<main id="main" class="public-wrap"><section class="panel">${empty('Could not load your workspace.',esc(error.message),'<button class="btn" data-action="retry">Try again</button>')}</section></main>`;bind();}
  }
}
async function discardDraft() {
  if(state.uploading){toast('Wait for the photo upload to finish.');return false;}
  if(!state.draft?.dirty)return true;
  if(!await confirmAction('Leave this check?','Your unsaved ratings will be discarded.','Discard check'))return false;
  for(const photo of Object.values(state.draft.photoData))await api(endpoint('photos/'+photo.id),{method:'DELETE'}).catch(()=>{});
  state.draft=null;return true;
}
async function navigate(view) {if(state.view==='check' && view!=='check' && !await discardDraft())return;state.view=view;state.draft=null;await render();window.scrollTo({top:0});}
function bind() {
  const pf=$('#photo-floor');if(pf)pf.addEventListener('change',async e=>{state.photoFilter.floor=e.target.value;await render();});
  const pd=$('#photo-date');if(pd)pd.addEventListener('change',async e=>{state.photoFilter.date=e.target.value;await render();});
  const workspace=$('#workspace');if(workspace)workspace.addEventListener('change',async e=>{const next=e.target.value;if(!await discardDraft()){e.target.value=state.workspace;return;}state.workspace=next;state.draft=null;localStorage.setItem('lane-workspace',next);await render();});
  const end=$('#week-end');if(end)end.addEventListener('change',async e=>{if(e.target.value){state.end=e.target.value;await render();}});
  const form=$('#check-form');if(form){form.addEventListener('input',e=>{const el=e.target;if(el.name==='issues'){state.draft.issues=[...form.querySelectorAll('input[name=issues]:checked')].map(x=>x.value);state.draft.dirty=true;}else if(el.name){state.draft[el.name]=el.type==='checkbox'?el.checked:el.value;state.draft.dirty=true;}});form.addEventListener('submit',saveCheck);form.querySelectorAll('[data-photo]').forEach(el=>el.addEventListener('change',uploadPhoto));}
  const floors=$('#floor-form');if(floors)floors.addEventListener('submit',async e=>{e.preventDefault();const b=$('button[type=submit]',floors);b.disabled=true;try{const fd=new FormData(floors);await api(endpoint('floors'),{method:'POST',body:JSON.stringify({name:fd.get('name'),area:(fd.get('area')||'').trim(),permission:fd.get('permission')==='on'})});await render();toast('Location added. Ready for its first check.');}catch(err){$('#floor-error').textContent=err.message;b.disabled=false;}});
}
async function saveCheck(event) {
  event.preventDefault();const button=$('button[type=submit]',event.target);button.disabled=true;
  try{
    const d=state.draft,payload={floor_id:d.floor_id,date:d.date,round:d.round,bio:d.bio,nonbio:d.nonbio,sanitary:d.sanitary||null,special:d.special||null,deep:!!d.deep,kept_separate:d.kept_separate===true||d.kept_separate==='yes'?true:d.kept_separate===false||d.kept_separate==='no'?false:null,issues:d.issues||[],note:d.note,photos:d.photos,human_confirmed:d.human_confirmed};
    await api(endpoint('checks'+(d.editing?'/'+encodeURIComponent(d.editing):'')),{method:d.editing?'PUT':'POST',body:JSON.stringify(payload)});
    state.draft=null;state.view='dashboard';state.end=payload.date;await render();window.scrollTo({top:0});toast('Observation saved. Your scores are up to date.');
  }catch(error){$('#check-error').textContent=error.message;button.disabled=false;}
}
async function uploadPhoto(event) {
  const file=event.target.files[0],stream=event.target.dataset.photo;if(!file)return;
  if(file.size>2*1024*1024){toast('Choose a photo smaller than 2 MB.');event.target.value='';return;}
  if(!await confirmAction('Share this bin photo?',`Confirm you have permission and the photo has no faces or personal details.${state.health.ai_configured?' It will be sent to AWS Bedrock for a suggestion.':''}`,'Upload photo')){event.target.value='';return;}
  const save=$('#check-form button[type=submit]');state.uploading=true;state.draft.dirty=true;save.disabled=true;event.target.disabled=true;
  try{
    const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Could not read photo.'));reader.readAsDataURL(file);});
    const photo=await api(endpoint('photos'),{method:'POST',body:JSON.stringify({image:data,stream,permission:true})});
    state.draft.photos.push(photo.id);state.draft.photoData[stream]=photo;state.draft.dirty=true;
    $('#photo-'+stream).innerHTML=photoZone(stream);toast('Photo attached. Choose and confirm your own rating.');
  }catch(error){toast(error.message);event.target.disabled=false;}finally{state.uploading=false;save.disabled=false;}
}
async function copyLink(token){const url=location.origin+'/card/'+token;try{await navigator.clipboard.writeText(url);toast('Private scorecard link copied.');}catch{const modal=$('#modal');modal.innerHTML=`<h2>Private scorecard link</h2><p>Copy this link and share it with the floor.</p><label class="field">Link<input value="${esc(url)}" readonly></label><form method="dialog" style="margin-top:20px"><button class="btn">Close</button></form>`;modal.showModal();$('input',modal).select();}}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-nav],[data-action],[data-card],[data-copy],[data-revoke],[data-edit],[data-delete-check],[data-delete-floor],[data-rename-floor],[data-remove-photo],[data-delete-photo],[data-photos-for],[data-switch-pilot],[data-followup]');if(!target)return;
  event.preventDefault();
  if(state.uploading){toast('Wait for the photo upload to finish.');return;}
  try{
    if(target.dataset.nav){await navigate(target.dataset.nav);return;}
    if(target.dataset.followup){state.draft=newDraft();state.draft.floor_id=target.dataset.followup;state.view='check';await render();window.scrollTo({top:0});return;}
    if(target.hasAttribute('data-switch-pilot')){state.workspace='pilot';state.view='setup';localStorage.setItem('lane-workspace','pilot');await render();return;}
    const action=target.dataset.action;
    if(action==='menu'){$('#sidebar').classList.toggle('open');return;}
    if(action==='retry'){await render();return;}
    if(action==='photo-clear'){state.photoFilter={floor:'',date:''};await render();return;}
    if(target.dataset.photosFor){const [floor,date]=target.dataset.photosFor.split('|');state.photoFilter={floor,date};await navigate('photos');return;}
    if(target.dataset.deletePhoto){if(!await confirmAction(t('Delete this photo?','यह फ़ोटो हटाएँ?'),t('It is removed permanently. The check and its ratings stay as they are.','यह हमेशा के लिए हट जाएगी। निरीक्षण और उसकी रेटिंग वैसी ही रहेंगी।'),t('Delete photo','फ़ोटो हटाएँ')))return;const pid=encodeURIComponent(target.dataset.deletePhoto),cid=target.dataset.check;await api(cid?endpoint('checks/'+encodeURIComponent(cid)+'/photos/'+pid):endpoint('photos/'+pid),{method:'DELETE'});await render();toast(t('Photo deleted.','फ़ोटो हटा दी गई।'));return;}
    if(action==='worker-create'){if(state.workerLink&&!await confirmAction('Make a new worker link?','The old link will stop working. Share the new one with collection staff.','Make new link'))return;await api(endpoint('worker-link'),{method:'POST'});await render();toast('Worker link ready. Share it with collection staff.');return;}
    if(action==='worker-revoke'){if(!await confirmAction('Turn off the worker link?','Staff using it will no longer be able to send reports.','Turn off'))return;await api(endpoint('worker-link'),{method:'DELETE'});await render();toast('Worker link turned off.');return;}
    if(action==='worker-copy'){await navigator.clipboard.writeText(workerLinkUrl());toast('Worker link copied.');return;}
    if(action==='language'){state.lang=state.lang==='en'?'hi':'en';localStorage.setItem('lane-lang',state.lang);document.documentElement.lang=state.lang;if(location.pathname.startsWith('/card/'))await publicPage();else await render();return;}
    if(action==='logout'){if(!await discardDraft())return;await api('/api/logout',{method:'POST'});state.draft=null;loginPage();return;}
    if(action==='print'){window.print();return;}
    if(target.dataset.card){target.disabled=true;const card=await api(endpoint('cards/'+target.dataset.card),{method:'POST',body:JSON.stringify({end:state.end})});state.view='cards';await render();await showCardCreated(card);return;}
    if(target.dataset.copy){await copyLink(target.dataset.copy);return;}
    if(target.dataset.revoke){if(await confirmAction('Revoke this private link?','Anyone with this link will lose access. You can generate a new card later.','Revoke link')){await api(endpoint('cards/'+target.dataset.revoke),{method:'DELETE'});await render();toast('Link revoked.');}return;}
    if(target.dataset.edit){state.draft=newDraft(state.data.recent.find(c=>c.id===target.dataset.edit));state.view='check';await render();window.scrollTo({top:0});return;}
    if(target.dataset.deleteCheck){if(await confirmAction('Delete this observation?','Its attached photos will be deleted and all workspace scorecard links revoked. This cannot be undone.','Delete check')){await api(endpoint('checks/'+encodeURIComponent(target.dataset.deleteCheck)),{method:'DELETE'});await render();toast('Observation deleted.');}return;}
    if(target.dataset.renameFloor){const f=state.floors.find(x=>x.id===target.dataset.renameFloor);if(f)renameLocation(f);return;}
    if(target.dataset.deleteFloor){if(await confirmAction('Remove this location and its data?','This deletes the location, its checks and attached photos, and revokes all scorecards in this workspace.','Remove floor')){await api(endpoint('floors/'+target.dataset.deleteFloor),{method:'DELETE'});await render();toast('Location removed.');}return;}
    if(target.dataset.removePhoto){const stream=target.dataset.removePhoto,p=state.draft.photoData[stream];await api(endpoint('photos/'+p.id),{method:'DELETE'});state.draft.photos=state.draft.photos.filter(id=>id!==p.id);delete state.draft.photoData[stream];$('#photo-'+stream).innerHTML=photoZone(stream);$('[data-photo]', $('#photo-'+stream)).addEventListener('change',uploadPhoto);return;}
  }catch(error){toast(error.message);target.disabled=false;}
});
async function showCardCreated(card){const modal=$('#modal');modal.innerHTML=`<h2>A little feedback, ready to share.</h2><p>The card for ${esc(card.name)} is ready. It contains a snapshot for ${dateLabel(card.start)}–${dateLabel(card.end)}.</p><div class="modal-actions"><form method="dialog"><button class="btn light">Close</button></form><a class="btn" href="/card/${card.token}" target="_blank" rel="noopener">Open scorecard ${icon('arrow')}</a></div>`;modal.showModal();}
function feedbackBlock(c){
  const f=c.feedback,L=x=>esc(x[state.lang]||x.en),n=f.norm;
  return `<div class="tip-box" style="margin-top:25px"><h3>${ISSUE_LABELS[f.issue]?.[0]||''} ${t('What went wrong','क्या ग़लत हुआ')}</h3><p>${L(f.what)} <span class="muted">${t(`Seen in ${f.times} of ${f.checks} checks this week.`,`इस हफ़्ते ${f.checks} में से ${f.times} निरीक्षणों में।`)}</span></p>
  <h3 style="margin-top:14px">${t('Why it matters','यह क्यों ज़रूरी है')}</h3><p>${L(f.why)}</p>
  ${n?`<h3 style="margin-top:14px">${t('Other locations','दूसरी जगहें')}</h3><p>${t(`${n.floors_without} of the other ${n.floors} locations had none of this mistake this week.`,`इस हफ़्ते बाक़ी ${n.floors} में से ${n.floors_without} जगहों पर ऐसा नहीं हुआ।`)}</p>`:''}
  <h3 style="margin-top:14px">${icon('leaf')} ${t('One thing to try','एक सुधार')}</h3><p>${L(f.fix)}</p></div>`;
}
async function publicPage(){
  const token=location.pathname.split('/')[2];
  try{
    const c=await api('/api/public/cards/'+encodeURIComponent(token));
    const shareText=`${c.source==='simulated'?'DEMO — simulated data. ':''}${c.name}: ${value(c.score)}/100. ${dateLabel(c.start)}–${dateLabel(c.end)}. ${location.origin}/card/${token}`;
    $('#app').innerHTML=`<main class="public-wrap" id="main">${brand}<div style="display:flex;justify-content:flex-end;margin-bottom:13px"><button class="lang" data-action="language">${state.lang==='en'?'हिन्दी':'English'}</button></div><article class="public-card"><header class="public-card-head"><span class="pill ${c.source==='simulated'?'amber':''}">${c.source==='simulated'?'DEMO · SIMULATED DATA':'REAL PILOT OBSERVATIONS'}</span><h1>${esc(c.name)}</h1><p class="muted" style="font-size:12px">${dateLabel(c.start)} – ${dateLabel(c.end)} · ${t('Your weekly scorecard','आपका साप्ताहिक स्कोरकार्ड')}</p><div class="public-score">${value(c.score)}<span> / 100</span></div><p class="muted" style="font-size:12px">${c.checks} ${t('checks','निरीक्षण')} · ${value(c.coverage,'%')} ${t('observation coverage','देखे गए कूड़ेदान')}</p></header><div class="public-card-body"><div class="comparison"><div><strong>${value(c.median)}</strong><small>${t('Campus median','कैंपस का मध्य स्कोर')} /100</small></div><div><strong>${c.compared_floors}</strong><small>${t('Locations with scored observations','स्कोर वाली जगहें')}</small></div></div>${['bio','nonbio'].map(s=>`<div class="bin-row"><span class="bin-icon ${s==='nonbio'?'dry':''}">${icon('bin')}</span><div class="bin-details"><div class="bin-title"><span>${s==='bio'?t('Green bin · degradable (kitchen waste)','हरा डिब्बा · गीला (रसोई) कचरा'):t('Blue bin · non-degradable (recyclable)','नीला डिब्बा · सूखा (रीसायकल) कचरा')}</span><strong>${value(c.streams[s])} /100</strong></div><div class="track ${s==='nonbio'?'dry':''}"><span style="width:${c.streams[s]||0}%"></span></div></div></div>`).join('')}${EXTRA_BINS.filter(([k])=>c.streams[k]!=null).map(([k,en,hi])=>`<div class="bin-row"><span class="bin-icon dry">${icon('bin')}</span><div class="bin-details"><div class="bin-title"><span>${t(en,hi)}</span><strong>${value(c.streams[k])} /100</strong></div><div class="track dry"><span style="width:${c.streams[k]||0}%"></span></div></div></div>`).join('')}${c.feedback?feedbackBlock(c):`<div class="tip-box" style="margin-top:25px"><h3>${icon('leaf')} ${t('One thing to try this week','इस हफ़्ते एक सुधार')}</h3><p>${esc(c.tip[state.lang]||c.tip.en)}</p></div>`}<p class="public-meta">${t('Human-confirmed observations · Rule-based guidance','मानव द्वारा पुष्टि किए गए निरीक्षण · निर्धारित मार्गदर्शन')}</p></div></article><div class="public-actions"><button class="btn" data-copy="${esc(token)}">${icon('share')} ${t('Copy private link','निजी लिंक कॉपी करें')}</button><a class="btn light" href="/guide">${icon('leaf')} ${t('Which bin? Check a receipt','कौन सा डिब्बा? रसीद देखें')}</a><a class="btn light" href="https://wa.me/?text=${encodeURIComponent(shareText)}" target="_blank" rel="noopener noreferrer">WhatsApp ${icon('arrow')}</a><button class="btn light" data-action="print">${t('Print','प्रिंट')}</button></div><p class="public-footer">${t('Small checks. Better habits. Let’s keep going.','छोटे निरीक्षण। बेहतर आदतें। चलिए जारी रखें।')}<br>${c.source==='simulated'?'This card is an example, not a real impact claim.':'Early pilot feedback, not proof of environmental impact.'}</p><p class="public-meta">Snapshot: ${esc(new Date(c.generated_at).toLocaleString('en-IN'))}<br>Anyone with this link can view this card. Ask your operator to revoke it if needed.</p></main>`;
  }catch(error){$('#app').innerHTML=`<main class="public-wrap" id="main">${brand}<section class="panel">${empty('This card is not available.',esc(error.message),'<a class="btn light" href="/">Back to workspace</a>')}</section></main>`;}
}
window.addEventListener('beforeunload',e=>{if(state.draft?.dirty){e.preventDefault();e.returnValue='';}});
document.documentElement.lang=state.lang;
if(location.pathname.startsWith('/card/'))publicPage();else render();
